"""Debates acrescentados em novembro de 2026 (quarta leva): longoprazismo e relativismo moral."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
TF, JE = 'Tecnologia e futuro', 'Justiça e Estado'

DEBATES4 = [
dict(s='longoprazismo', n='Devemos priorizar o futuro distante?', t=TF, r='Se as pessoas futuras contam e podem ser trilhões, o longo prazo domina tudo? Ou isso é um cheque em branco contra o presente?',
 v='O longoprazismo diz que influenciar positivamente o futuro de longo prazo é uma das prioridades morais do nosso tempo: as pessoas que podem vir a existir são muito mais numerosas do que as vivas, e o que fazemos hoje (riscos existenciais, inteligência artificial, instituições) afeta todas elas. Os críticos aceitam que o futuro conta e discordam do peso, da matemática e das prioridades que o argumento gera.',
 lados=[('A favor', ['Imparcialidade no tempo: uma pessoa não vale menos por nascer em 2200, como não vale menos por nascer em outro país. Veja o atemporalismo.', 'Escala: se a humanidade durar o que outras espécies duraram, as pessoas futuras serão a quase totalidade das que existirão; ignorá-las é o maior ponto cego possível.', 'Alavanca: há momentos em que o futuro está mais em nossas mãos do que nunca, por tecnologias que podem extinguir ou aprisionar a humanidade; evitar o irreversível é barato comparado ao que protege (Ord).', 'Não compete com o presente: pandemias, guerra nuclear e instituições corrigíveis beneficiam quem vive hoje também.']),
        ('Contra, ou com fortes ressalvas', ['Fanatismo: números astronômicos multiplicados por probabilidades minúsculas justificam qualquer sacrifício presente; o argumento não tem freio interno.', 'Incerteza: ninguém sabe prever efeitos a séculos; a confiança em intervenções de longo prazo é mais fraca do que a aritmética sugere.', 'Negligência do presente: há sofrimento certo agora, e recursos desviados para cenários especulativos têm custo em vidas reais.', 'Pessoas possíveis: há dever de criar pessoas felizes? A visão focada no sofrimento diz que o dever é evitar que o futuro seja ruim, não garantir que seja populoso; isso muda as prioridades de “existir” para “não sofrer”.', 'Poder: “pelo bem das gerações futuras” é uma justificativa que já serviu a concentrar poder; instituições plurais protegem melhor do que planos grandiosos.'])],
 c=['Longoprazismo fraco (o futuro conta, e os riscos irreversíveis merecem atenção) é quase consensual; o forte (o futuro domina as prioridades) é o que se discute.', 'Riscos X e riscos S levam a agendas parecidas em muita coisa e divergem no valor de garantir um futuro populoso.', 'A crítica do fanatismo vale para qualquer teoria que agrega sem limite, não só para o longoprazismo; a resposta usual é limitar a agregação e focar em riscos concretos.'],
 p=('parcial', 'O longoprazismo fraco está bem fundamentado: a data de nascimento não é razão moral, e evitar catástrofes irreversíveis é prioridade em quase qualquer teoria. O forte não convence a maioria: a aritmética de números astronômicos é frágil, a incerteza é maior do que o argumento admite, e a prioridade a criar vidas felizes é contestada pelas éticas focadas no sofrimento. O que fica: levar o futuro a sério, com foco no irreversível e em instituições capazes de corrigir erros, sem sacrificar quem sofre agora.'),
 teorias=[('temporalismo', 'Atemporalismo', 'A favor do princípio: o tempo não muda o valor de um sofrimento ou de uma vida.'), ('utilitarismo-classico', 'Utilitarismo total', 'A favor, e com o risco do fanatismo: quanto mais vidas boas, melhor.'), ('prioridade-ao-sofrimento', 'Prioridade ao sofrimento', 'A favor de evitar futuros ruins; contra a prioridade a criar futuros populosos.'), ('deontologia-de-direitos', 'Direitos', 'Deveres com as gerações futuras existem, mas não autorizam violar direitos presentes.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber em que geração nasceria, você aceitaria regras de poupança justa, não sacrifício ilimitado.')],
 licoes=['geracoes-futuras', 'riscos-s-e-riscos-x', 'etica-populacional', 'teoria-da-decisao-e-etica'],
 fx=[('Longtermism (Wikipédia)', WE + 'Longtermism'), ('The Precipice', 'https://theprecipice.com/'), ('What We Owe the Future', 'https://whatweowethefuture.com/'), ('Avoiding the Worst', 'https://centerforreducingsuffering.org/research/avoiding-the-worst/'), ('Intergenerational Justice (Stanford Encyclopedia)', SEP + 'justice-intergenerational/')]),

dict(s='relativismo-moral', n='Podemos julgar outras culturas?', t=JE, r='“Cada cultura tem sua moral, e ninguém pode julgar.” A frase soa tolerante. Levada a sério, ela impede dizer que a escravidão era errada.',
 v='O relativismo moral diz que o certo e o errado dependem da cultura (ou da pessoa), sem um padrão que valha para todos. É a resposta mais comum quando alguém ouve sobre práticas de outra sociedade: “quem somos nós para julgar?”. A pergunta é se essa posição se sustenta, e o que a substitui sem cair no imperialismo moral que ela teme.',
 lados=[('O que o relativismo acerta', ['Humildade: a nossa cultura também tem pontos cegos, e julgar de fora já serviu para dominar, escravizar e “civilizar”.', 'Muito do que chamamos de moral é convenção: vestir-se, comer, cumprimentar. Confundir etiqueta com ética é um erro comum.', 'Desacordo real existe, e a certeza moral já causou guerras.']),
        ('Por que não se sustenta como teoria', ['Perde o desacordo e o progresso: se cada cultura está certa por definição, a abolição e o voto feminino não foram avanços, só mudanças; e quem defende e quem condena a escravidão não discordam, só falam de referenciais diferentes.', 'Quem fala pela cultura? Dentro de qualquer sociedade há dissidentes, e quase sempre são as vítimas da prática; o relativismo dá a última palavra a quem manda.', 'Autorrefutação: “toda moral é relativa, logo seja tolerante” é um juízo que pretende valer para todos.', 'Rachels: as diferenças entre culturas são menores do que parecem, e muitas vêm de crenças factuais (sobre a morte, sobre os deuses) e do círculo de quem conta, não de valores básicos diferentes.', 'A alternativa ao relativismo não é a arrogância: é a imparcialidade, que julga práticas, não povos, e julga a própria cultura com a mesma régua.'])],
 c=['Relativismo descritivo (culturas diferem) é verdadeiro; o normativo (logo, não há padrão) não se segue dele.', 'Tolerância e relativismo são diferentes: a tolerância respeita pessoas, admite que podemos estar errados e tem limite no dano; o relativismo não tem critério para limite nenhum.', 'O relativismo de conveniência, usado só quando a conclusão incomoda, é o mais comum, e é o menos defensável.'],
 p=('forte', 'Entre filósofos, o relativismo moral normativo é quase unanimemente rejeitado, porque torna impossível o erro, o desacordo e o progresso, e porque silencia quem sofre dentro de cada cultura. O que ele acerta (humildade, distinção entre convenção e moral, desconfiança do imperialismo) é preservado pela imparcialidade, que julga práticas com uma régua que vale para todos, inclusive para quem julga. Em metaética, versões sofisticadas (Harman, Wong) continuam em debate, mas sem a conclusão de que “ninguém pode julgar”.'),
 teorias=[('relativismo-cultural', 'Relativismo cultural', 'Certo e errado dependem das normas de cada cultura; é a posição em exame.'), ('relativismo-metaetico', 'Relativismo metaético', 'A versão sofisticada: verdade moral relativa a um referencial, com desacordo sobre qual adotar.'), ('prescritivismo', 'Prescritivismo (Hare)', 'Julgar moralmente é universalizar: a frase “cada cultura tem a sua” não é um juízo moral, é a recusa de fazer um.'), ('utilitarismo-classico', 'Utilitarismo', 'O sofrimento é o mesmo em qualquer cultura; a prática que o causa pode ser julgada em qualquer lugar.'), ('deontologia-kantiana', 'Kant', 'Dignidade não depende de fronteira cultural.'), ('quase-realismo', 'Quase-realismo', 'Mesmo sem fatos morais, podemos dizer que a escravidão era errada quando todos a aprovavam.')],
 licoes=['egoismo-relativismo-e-ceticismo', 'relativismo-e-quietismo', 'imparcialidade', 'progresso-moral'],
 fx=[('Moral Relativism (Stanford Encyclopedia)', SEP + 'moral-relativism/'), ('Os Elementos da Filosofia Moral', 'https://www.google.com/search?tbm=bks&q=Rachels+Os+Elementos+da+Filosofia+Moral'), ('Relativismo e círculo moral (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/relativismo-e-circulo-moral.html')]),
]
assert len({d['s'] for d in DEBATES4}) == len(DEBATES4)
